import (
	"archive/zip"
	"os"
	"strings"
	"time"
)

func main() {
	when := time.Date(2024, 2, 29, 13, 37, 42, 0, time.UTC)
	text := strings.Repeat("a line of a text that DEFLATE makes smaller\n", 70)
	f, _ := os.Create(os.Args[1])
	w := zip.NewWriter(f)
	w.SetComment("made by archive/zip")
	add := func(h *zip.FileHeader, body string) {
		h.Modified = when
		fw, err := w.CreateHeader(h)
		if err != nil {
			panic(err)
		}
		fw.Write([]byte(body))
	}
	add(&zip.FileHeader{Name: "deflated.txt", Method: zip.Deflate}, text)
	add(&zip.FileHeader{Name: "stored.txt", Method: zip.Store}, "stored as it is\n")
	add(&zip.FileHeader{Name: "dir/"}, "")
	run := &zip.FileHeader{Name: "dir/run.sh", Method: zip.Deflate}
	run.SetMode(0o755)
	add(run, "#!/bin/sh\n")
	link := &zip.FileHeader{Name: "link", Method: zip.Store}
	link.SetMode(os.ModeSymlink | 0o777)
	add(link, "dir/run.sh")
