# What Python's zipfile reads from each archive, as the lines of Bun's `readZip` hook.
import base64, json, struct, sys, zipfile, zlib, os

def escape(name: bytes) -> str:
    out = []
    for b in name:
        if b == 0x09: out.append('\\t')
        elif b == 0x0a: out.append('\\n')
        elif b == 0x0d: out.append('\\r')
        elif b in (0x22, 0x27, 0x5c): out.append('\\' + chr(b))
        elif 0x20 <= b <= 0x7e: out.append(chr(b))
        else: out.append('\\x%02x' % b)
    return ''.join(out)

def utc_mtime(extra: bytes):
    at = 0
    while at + 4 <= len(extra):
        tag, size = struct.unpack_from('<HH', extra, at)
        body = extra[at + 4:at + 4 + size]
        if tag == 0x5455 and len(body) >= 5 and body[0] & 1:
            return struct.unpack_from('<I', body, 1)[0]
        at += 4 + size
    return None

def expected(path):
    lines = []
    with zipfile.ZipFile(path) as z:
        for i in z.infolist():
            data = z.read(i)
            unix = (i.external_attr >> 16) if i.create_system == 3 else 0
            if i.filename.endswith('/'): kind = 'directory'
            elif unix & 0o170000 == 0o120000: kind = 'symlink'
            else: kind = 'file'
            perm = unix & 0o7777 or (0o755 if kind == 'directory' else 0o644)
            size = len(data) if kind == 'file' else 0
            mtime = utc_mtime(i.extra)
            line = '%s perm=%o size=%d mtime=%d path="%s"' % (kind, perm, size, mtime or 0, escape(i.filename.encode()))
            if mtime is None:
                line += ' dos=%04d-%02d-%02dT%02d:%02d:%02d' % i.date_time
            if kind == 'symlink':
                line += ' -> "%s"' % escape(data)
            lines.append(line)
            if size:
                lines.append('  data 0+%d' % size)
            lines.append('  end %d crc32=%08x' % (size, zlib.crc32(data) if kind == 'file' else 0))
    lines.append('end')
    return '\n'.join(lines) + '\n'

writers = {
    'python': 'Python 3.13.5, zipfile',
    'go': 'Go 1.24.4, archive/zip',
    'node': 'Node.js 26.12.1, zlib.createZipArchiveSync',
}
out = []
for name in sorted(os.listdir('out')):
    raw = open('out/' + name, 'rb').read()
    out.append({
        'name': name[:-4],
        'writer': writers[name.split('-')[0]],
        'zip': base64.b64encode(raw).decode(),
        'expected': expected('out/' + name),
    })
json.dump(out, open('zip-writers.json', 'w'), indent=2, ensure_ascii=False)
print(len(out), 'archives', sum(len(x['zip']) for x in out), 'base64 bytes')
